        std::vector<Polygon2d> holes;
        for (auto hole_it = it->holes_begin(); hole_it != it->holes_end(); ++hole_it) {
            holes.push_back(hole_it->outer_boundary());
        }
        result.push_back(PolygonWithHoles2d(polygon, holes));
    }
    return result;
}
